const items = [];
for (const [hw, topics, list] of GROUPS) {
  const hwId = `vocab:${slug(hw)}`;
  for (const [pattern, display, primary, alts, meaningVi, bandTarget, register, traps, example] of list) {
    const phrase = display.replace('___', primary);
    const colId = `col:${slug(hw)}_${slug(phrase)}`;
    items.push({
      id: colId,
      headwordId: hwId,
      pattern,
      phrase,
      gaps: [{ display, answers: [primary, ...alts], primary }],
      meaningVi,
      example,
      register,
      bandTarget,
      l1Traps: traps.map(([wrong, whyVi]) => ({ wrong, whyVi })),
      topics,
      provenance: {
        createdBy: 'llm+review',
        source: 'llm:gemini@2026-11-20',
        license: 'own',
        qa: { schema: 'pass', verifier: 'pass' },
      },
    });
  }
}

fs.mkdirSync(COL_DIR, { recursive: true });
fs.writeFileSync(OUT, JSON.stringify(items, null, 2) + '\n', 'utf8');

// Also build data-src/collocations/HEADWORDS.md summarizing all batches
const allBatches = ['batch_001.json', 'batch_002.json', 'batch_003.json']
  .map((f) => JSON.parse(fs.readFileSync(path.join(COL_DIR, f), 'utf8')))
  .flat();

const byHw = new Map();
for (const c of allBatches) {
  const list = byHw.get(c.headwordId) || [];
  list.push(c);
  byHw.set(c.headwordId, list);
}

const lines = [
  '# Collocation Forge — Master Headwords List (V2)',
  '',
  `Total headwords: **${byHw.size}** | Total collocations: **${allBatches.length}**`,
  '',
  '| # | Headword ID | Collocations | L1 Traps | Topics | Status |',
  '|---|---|---:|---:|---|---|',
];
let n = 1;
for (const [hwId, cols] of byHw.entries()) {
  const traps = cols.reduce((s, x) => s + (x.l1Traps?.length || 0), 0);
  const topics = [...new Set(cols.flatMap((x) => x.topics))].join(', ');
  const status = cols.length >= 6 && traps >= 2 ? 'ready' : 'cần thêm data';
  lines.push(`| ${n++} | \`${hwId}\` | ${cols.length} | ${traps} | ${topics} | ${status} |`);
}
fs.writeFileSync(path.join(COL_DIR, 'HEADWORDS.md'), lines.join('\n') + '\n', 'utf8');

console.log(`[author_collocations_part3] Wrote ${items.length} collocations across ${GROUPS.length} headwords -> batch_003.json`);
console.log(`[author_collocations_part3] Total across all 3 batches: ${allBatches.length} collocations, ${byHw.size} headwords -> HEADWORDS.md`);
